window.RP_SESSION={"id":"S-b99aabaeff17","messages":[{"id":"RP-II-0078939","time":"2026-04-10T15:48:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뒹굴뒹굴뒹굴뒹굴","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078940","time":"2026-04-10T15:49:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"토끼다. 토끼.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078941","time":"2026-04-10T15:49:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"산~토끼 토끼야, 어디를 가느냐.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078942","time":"2026-04-10T15:51:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 이리와.\n\n \"      \"\n\n 아잇. 또 목소리 안 나온다. 일 할 땐 이런 적 없는 건 다행이지지만.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078943","time":"2026-04-10T15:51:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" !매력","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078944","time":"2026-04-10T15:51:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'사이먼 피터 포레스트'의 매력 판정 :\n[9] + [1] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0078945","time":"2026-04-10T15:51:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078946","time":"2026-04-10T15:51:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아도니스'의 매력 판정 :\n[10] + [3] = [13]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0078947","time":"2026-04-10T15:53:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 토끼 품에 안고 쓰다듬으며 마저 흙바닥을  뒹굴댄다.\n\n '토끼는 성대를 못 쓴다는데.'\n\n 토끼는 노래로 구애를 할 필요가 없는, 연약한 초식동물이니 목소리가 쓸 일이 없던건 이상한 일이 아니었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078948","time":"2026-04-10T15:53:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 헉.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078949","time":"2026-04-10T15:57:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그러고보니 내 `가족`은 정말 말이 없었지. 사람 사회는 그걸 말 수가 적다라는 표현으로 쓰던데, 내 `가족`은. 진짜로 목소리를 들은 적이 없어.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078950","time":"2026-04-10T15:59:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 나는 결국 소리를 내야만 의미를 전달할 수 있는데, '가족'들은 신기하게도 아무 소리도 안 냈지. 진정한 마음의 관계를 얻으려면 언어 따윈 방해일 뿐이라나 뭐라나.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078951","time":"2026-04-10T16:00:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 헉, 어쩌면 그-그들(they)도 토끼와 같았던거 아닐까?","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078952","time":"2026-04-10T16:01:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"토끼는 소리를 쓰지 않아도 충분히 자연의 일부로 기능할 수 있으니까. 어쩌면 내 목소리도 퇴화되는 중일지도...!","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078953","time":"2026-04-10T16:02:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"음... 아닌데, 나 요새 말 잘하는데!(아님)","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078954","time":"2026-04-10T16:03:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그렇게 치면 숲 속에 있을 때 퇴화 됐어야 하는 거 아닌가? 기회는 몇 번이고 있었을테니.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078955","time":"2026-04-10T16:04:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 이유는 기억이 안 나지만, `가족`을 처음 만났을 때의 나는 정말로 목소리를 못 내고 있었다. 왜였을까? 나이 좀 먹고나서 무언갈 말했고, 그 이후로 소리가 돌아왔던 거 같은데.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078956","time":"2026-04-10T16:05:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"                                 ?\"\n\n ...내가 뭐라고 말했더라? `가족`이 뭐라고 반응했던가? 그래도 그 뒤로 딱히 사람 말은 안 했던 건 기억난다.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078957","time":"2026-04-10T16:05:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"왜였지?","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078958","time":"2026-04-10T16:07:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그리고나서 처음으로 한 사람 말은.\n\n -\"아, 아. 아아아아아아아아악...!\"\n\n 이거였지.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078959","time":"2026-04-10T16:07:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그러고보니 2달 전까진 제대로 큰 소리 낼 수 있었구나.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078960","time":"2026-04-10T16:08:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 역시 퇴화되고 있는 걸지도.\n\n \"흐음...\"\n\n 아, 아닌가?","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078961","time":"2026-04-10T16:09:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"...배고프다.\"\n\n 토끼 빤-히...","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078962","time":"2026-04-10T16:09:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"빤히... 빤히...","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078963","time":"2026-04-10T16:09:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"헉","characters":[]},{"id":"RP-II-0078964","time":"2026-04-10T16:10:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '장난이야. 사람 사회에선 굳이 널 먹을 필요가 없더라.'\n\n 토끼 볼 부비부비.\n\n '이상하지?'","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078965","time":"2026-04-10T16:10:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '과자 먹고 싶네.'\n\n 토끼 품에 안고 길드 안에 들어온다. 바닥에 흙먼지를 흘리며...","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078966","time":"2026-04-10T16:11:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" -fin","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0078967","time":"2026-04-10T16:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
